import{_ as l,o as t,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Science User Group Meetup - July 2025","description":"","frontmatter":{"title":"Ceph Science User Group Meetup - July 2025","date":"2025-07-30T00:00:00.000Z","updated":"2025-07-31T00:00:00.000Z","tags":["分布式存储","Ceph","性能优化","硬件选型","碳成本"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Science_User_Group_Meetup_-_July_2025.md","filePath":"posts/2025/Ceph_Science_User_Group_Meetup_-_July_2025.md","lastUpdated":1780459816000}'),a={name:"posts/2025/Ceph_Science_User_Group_Meetup_-_July_2025.md"};function r(s,e,n,p,u,_){return t(),i("div",null,[...e[0]||(e[0]=[o('<h3 id="ceph-月度会议纪要-2024年x月x日" tabindex="-1">Ceph 月度会议纪要（2024年X月X日） <a class="header-anchor" href="#ceph-月度会议纪要-2024年x月x日" aria-label="Permalink to &quot;Ceph 月度会议纪要（2024年X月X日）&quot;">​</a></h3><h4 id="_1-会议主题" tabindex="-1"><strong>1. 会议主题</strong> <a class="header-anchor" href="#_1-会议主题" aria-label="Permalink to &quot;**1. 会议主题**&quot;">​</a></h4><p>本次会议的主题为《分布式存储（Ceph）的电力与碳成本分析》，由英国SDFC研究员Tom主讲。</p><h4 id="_2-核心讨论内容" tabindex="-1"><strong>2. 核心讨论内容</strong> <a class="header-anchor" href="#_2-核心讨论内容" aria-label="Permalink to &quot;**2. 核心讨论内容**&quot;">​</a></h4><p><strong>2.1 研究背景与目标</strong></p><ul><li>研究HDD（机械硬盘）与SSD（闪存）在Ceph集群中的性能/成本/功耗差异。</li><li>对比三种硬件方案： <ul><li>标准HDD（8TB）</li><li>高密度HDD（24TB）</li><li>闪存方案（15TB TLC SSD）</li></ul></li><li>使用<code>RADOS Bench</code>进行混合负载（50%读/50%写）压测，监控节点功耗，并计算碳成本。</li></ul><p><strong>2.2 关键发现</strong></p><ul><li>闪存方案在空闲时与高密度HDD功耗相近，但满载时功耗增加80%。</li><li>高密度HDD的性能/容量比下降明显。</li><li>小IOPS场景下，闪存每瓦特IOPS效率更高。</li><li>流式吞吐（大块IO）下，三种方案差异不显著。</li><li>闪存方案的单位性能碳效率更优。</li></ul><p><strong>2.3 后续行动建议</strong></p><ul><li>考虑更高密度QLC SSD（如60TB）以进一步优化功耗与成本。</li><li>测试不同EC（纠删码）布局对性能的影响。</li></ul><h4 id="_3-其他技术讨论" tabindex="-1"><strong>3. 其他技术讨论</strong> <a class="header-anchor" href="#_3-其他技术讨论" aria-label="Permalink to &quot;**3. 其他技术讨论**&quot;">​</a></h4><p><strong>3.1 Ceph版本升级（Quincy → Squid</strong>）</p><ul><li>部分用户反馈从Quincy跳过Reef直接升级至Squid的可行性，需验证MDS稳定性问题。</li><li>建议等待Squid后续补丁修复已知问题。</li></ul><p><strong>3.2 节点物理迁移与CRUSH Map保留</strong></p><ul><li>确保主机名/IP变更后，OSD在CRUSH Map中的位置不变。</li><li>操作建议：禁用自动重平衡，使用<code>pg-remapper</code>工具手动修复PG分布。</li></ul><p><strong>3.3 磁盘故障与替换</strong></p><ul><li>HDD扇区错误导致静默数据不一致，<code>cephadm replace</code>操作依赖PG完全恢复。</li><li>临时方案：启用<code>PG auto-repair</code>或强制全盘重写。</li></ul><p><strong>3.4 集群日志优化</strong></p><ul><li>大规模集群（8000+ OSD）中，日志同步导致Monitor性能下降。</li><li>临时解决：禁用<code>cluster_log_to_monitors</code>。</li></ul><h4 id="_4-行动计划" tabindex="-1"><strong>4. 行动计划</strong> <a class="header-anchor" href="#_4-行动计划" aria-label="Permalink to &quot;**4. 行动计划**&quot;">​</a></h4><p>| 任务 | 负责人 | 时间线 | ||--|--| | 测试QLC SSD在Ceph中的性能 | Tom | 2024 Q4 | | 提交Squid升级问题到邮件列表 | Matia | 2024-09 | | 验证cluster_log_to_monitors关闭影响 | 社区成员 | 持续 |</p><h4 id="_5-下期会议预告" tabindex="-1"><strong>5. 下期会议预告</strong> <a class="header-anchor" href="#_5-下期会议预告" aria-label="Permalink to &quot;**5. 下期会议预告**&quot;">​</a></h4><ul><li>时间：2024年9月23日（周二）</li><li>议题征集：鼓励提交短篇技术分享。</li><li>往期资料：会议录像及幻灯片已上传至<a href="./链接.html">YouTube</a>和<a href="./链接.html">GitHub仓库</a>。</li></ul><p><strong>备注</strong>：关键词保留（如CRUSH、RADOS、Bluestore等）以方便技术检索。会议录制：本场录像将后期发布，请关注邮件通知。</p>',24)])])}const d=l(a,[["render",r]]);export{h as __pageData,d as default};
